sys_script_client.script:
function onSubmit() {
    var ga = new GlideAjax('x_1834930_office_0.OfficeBaseValidation');
    ga.addParam('sysparm_name', g_form.getValue('name'));
    ga.addParam('sysparm_city', g_form.getValue('city'));
    ga.addParam('sysparm_state', g_form.getValue('state'));
    ga.addParam('sysparm_sys_id', g_form.getUniqueValue());

  //  var submitted = false;

    ga.getXMLAnswer(function(response) {
        if (response === 'duplicate_name') {
            g_form.addErrorMessage('A base with this name already exists.');
        } else if (response === 'duplicate_city_state') {
            g_form.addErrorMessage('A base with this city and state already exists.');
 //       } else if (!submitted) {
      //      submitted = true;
   //         g_form.submit();
        }
    });

    return false;
}
